import fetch from 'node-fetch';

const SHOP = process.env.SHOPIFY_SHOP; // e.g. "my-shop" or "my-shop.myshopify.com"
const ADMIN_TOKEN = process.env.SHOPIFY_ADMIN_API_ACCESS_TOKEN; // permanent token

if (!SHOP || !ADMIN_TOKEN) {
  throw new Error('Set SHOPIFY_SHOP and SHOPIFY_ADMIN_API_ACCESS_TOKEN.');
}

function normalizeShop(shop) {
  return shop.includes('.myshopify.com') ? shop : `${shop}.myshopify.com`;
}

const shopDomain = normalizeShop(SHOP);

async function graphql(query, variables = {}) {
  const res = await fetch(`https://${shopDomain}/admin/api/2025-01/graphql.json`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'X-Shopify-Access-Token': ADMIN_TOKEN,
    },
    body: JSON.stringify({ query, variables }),
  });
  if (!res.ok) throw new Error(`GraphQL failed: ${res.status}`);
  const payload = await res.json();
  if (payload.errors?.length) throw new Error(`GraphQL errors: ${JSON.stringify(payload.errors)}`);
  return payload.data;
}

(async () => {
  const query = '{ products(first: 3) { edges { node { id title handle } } } }';
  const data = await graphql(query);
  console.log(JSON.stringify(data, null, 2));
})();⁸

